/** Actual4x2 board/cog/manual inputs/native target state, reload and genuine two-chunk return. STAGED, UNRUN.
 * Root-reserved scene23000..23032,z0..24; unload24400,20,24400. No fabricated DisplayLink block/transport.
 */
final class FlapDisplayRenderingTest {
    private static final BlockPos P=new BlockPos(23005,7,5),COG=P.west(),MOTOR=COG.north();
    private static final String MANUAL="CREATE NATIVE 26.3";
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 23006.0 10.0 10.0");context.waitFor(client->Math.abs(client.player.getX()-23006.0)<.1&&Math.abs(client.player.getZ()-10.0)<.1,300);context.waitFor(client->client.level.isLoaded(P.east(3))&&Math.abs(client.player.getX()-23006)<.1,500);server.runCommand("fill 23000 4 0 23032 4 24 minecraft:smooth_quartz");
        for(int y=0;y<2;y++)for(int x=0;x<4;x++)block(world,P.east(x).below(y),"create:display_board[facing=south,waterlogged=false]");block(world,COG,"create:cogwheel[axis=z]");block(world,MOTOR,"create:creative_motor[facing=south]");server.runOnServer(ignored->((KineticBlockEntity)LoadedLevelAccess.blockEntity(world.getConnection().getServerLevel(),MOTOR)).setGeneratedSpeed(64));
        waitServer(context,world,level->{var board=board(level);return board!=null&&board.isController&&board.xSize==4&&board.ySize==2&&Math.abs(board.getSpeed())==64;},300,"Actual4x2 source rectangle/cog/motor network failed to become a running controller");
        var name=new ItemStack(Items.NAME_TAG);name.set(DataComponents.CUSTOM_NAME,Component.literal(MANUAL));slot(world,0,name);slot(world,1,new ItemStack(Items.DYE.pick(DyeColor.BLUE),2));slot(world,2,new ItemStack(Items.GLOW_INK_SAC,2));var stopped=new ItemStack(Items.NAME_TAG);stopped.set(DataComponents.CUSTOM_NAME,Component.literal("STOPPED"));slot(world,3,stopped);
        server.runCommand("gamemode survival @p");server.runCommand("tp @p 23006.5 5 8.5");context.waitFor(client->Math.abs(client.player.getX()-23006.5)<.1&&Math.abs(client.player.getZ()-8.5)<.1,300);context.getInput().pressKey(InputConstants.KEY_1);context.waitFor(client->client.player.getMainHandItem().is(Items.NAME_TAG),150);use(context,0);
        waitServer(context,world,level->text(level,0).equals(MANUAL)&&board(level).manualLines[0],200,"Actual name-tag input did not update the real controller manual line");context.waitFor(client->client.player.getMainHandItem().getCount()==1,100);
        context.getInput().pressKey(InputConstants.KEY_2);context.waitFor(client->client.player.getMainHandItem().is(Items.DYE.pick(DyeColor.BLUE)),150);use(context,0);waitServer(context,world,level->board(level).colour[0]==DyeColor.BLUE,150,"Actual native dye input failed to change selected source row");context.waitFor(client->client.player.getMainHandItem().getCount()==2,100);
        context.getInput().pressKey(InputConstants.KEY_3);context.waitFor(client->client.player.getMainHandItem().is(Items.GLOW_INK_SAC),150);use(context,0);waitServer(context,world,level->board(level).isLineGlowing(0),150,"Actual native ink interaction did not enable source row glow");context.waitFor(client->client.player.getMainHandItem().getCount()==2,100);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var result=new DisplayBoardTarget(level,P.east(3).below()).acceptFlapText(2,List.of(List.of(Component.literal("NATIVE"),Component.literal("256")),List.of(Component.literal("FABRIC"),Component.literal("26.3"))),(board,layout,row)->layout.configure("Actual native scene",List.of(new FlapDisplaySection(63,"alphabet",false,true),new FlapDisplaySection(42,"numeric",false,false).rightAligned())),false,row->false);if(result.changedRows()!=2)throw new AssertionError("Concrete common target did not mutate the two real sectioned rows");});
        waitServer(context,world,level->text(level,0).equals(MANUAL)&&board(level).getLines().get(2).isLayout("Actual native scene")&&board(level).getLines().get(3).getSections().get(1).getText().getString().equals("26.3"),150,"Actual direct native target state is missing");context.waitTicks(80);verify(context,true);world.getConnection().waitForChunksRender();look(context,Vec3.atCenterOf(P.east()).add(.5,-.3,0));screenshot(context,"create-vulkan-native-flap-display-real-manual-glow-and-sectioned-target");
        var oldModel=context.computeOnClient(client->client.getModelManager().getBlockStateModelSet().get(AllBlocks.DISPLAY_BOARD.defaultBlockState()));var oldCycle=context.computeOnClient(client->FlapDisplaySection.getFlapCycle("alphabet"));var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);reload.join();context.runOnClient(client->{if(client.getModelManager().getBlockStateModelSet().get(AllBlocks.DISPLAY_BOARD.defaultBlockState())==oldModel||FlapDisplaySection.getFlapCycle("alphabet")==oldCycle)throw new AssertionError("Native reload retained a stale actual board model/flap language cycle cache");});verify(context,true);
        var oldController=new AtomicReference<FlapDisplayBlockEntity>();var oldFarPart=new AtomicReference<FlapDisplayBlockEntity>();server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();oldController.set(board(level));oldFarPart.set(part(level,P.east(3).below()));});server.runCommand("gamemode spectator @p");server.runCommand("tp @p 24400 20 24400");
        waitServer(context,world,level->level.getChunkSource().getChunkNow(P.getX()>>4,P.getZ()>>4)==null&&level.getChunkSource().getChunkNow(P.east(3).getX()>>4,P.getZ()>>4)==null,800,"Both actual display fixture chunks failed to unload");
        NativeFixtureChunkUnload.finish(context,world,oldController.get(),oldFarPart.get());
        server.runCommand("tp @p 23006.0 10.0 10.0");context.waitFor(client->Math.abs(client.player.getX()-23006.0)<.1&&Math.abs(client.player.getZ()-10.0)<.1,300);waitServer(context,world,level->{var board=board(level);return board!=null&&board!=oldController.get()&&part(level,P.east(3).below())!=null&&part(level,P.east(3).below())!=oldFarPart.get()&&board.isController&&board.xSize==4&&board.ySize==2&&Math.abs(board.getSpeed())==64&&text(level,0).equals(MANUAL)&&board.manualLines[0]&&board.colour[0]==DyeColor.BLUE&&board.isLineGlowing(0)&&board.getLines().get(3).getSections().size()==2&&board.getLines().get(3).getSections().get(1).getText().getString().equals("26.3");},600,"Actual chunk return lost source controller/text/layout/style or failed to restore real kinetic supply");context.waitFor(client->client.level.isLoaded(P)&&client.level.isLoaded(P.east(3).below()),300);context.waitTicks(80);verify(context,true);world.getConnection().waitForChunksRender();screenshot(context,"create-vulkan-native-flap-display-real-data-after-two-chunk-return");
        block(world,COG,"minecraft:air");waitServer(context,world,level->board(level).getSpeed()==0&&!board(level).isSpeedRequirementFulfilled(),200,"Real broken cog supply did not stop native display");context.waitFor(client->LoadedLevelAccess.blockEntity(client.level,P)instanceof FlapDisplayBlockEntity board&&!board.isSpeedRequirementFulfilled(),200);verify(context,false);server.runCommand("gamemode survival @p");server.runCommand("tp @p 23006.5 5 8.5");context.waitFor(client->Math.abs(client.player.getX()-23006.5)<.1&&Math.abs(client.player.getZ()-8.5)<.1,300);context.getInput().pressKey(InputConstants.KEY_4);context.waitFor(client->client.player.getMainHandItem().getHoverName().getString().equals("STOPPED"),150);use(context,0);context.waitTicks(12);waitServer(context,world,level->text(level,0).equals(MANUAL),100,"Stopped real board incorrectly accepted a manual text change");screenshot(context,"create-vulkan-native-flap-display-real-disconnected-cog-preserves-text");
    }
    private static void verify(ClientGameTestContext context,boolean running){context.runOnClient(client->{
        var entity=(FlapDisplayBlockEntity)LoadedLevelAccess.blockEntity(client.level,P);var state=(FlapDisplayRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(entity,.5f,null,true);if(state==null||!state.controller||state.running!=running||state.width!=4||state.height!=2||state.cog.isEmpty()||state.glyphs.isEmpty())throw new AssertionError("Actual native source board glyph/cog/controller state missing");if(state.glyphs.stream().noneMatch(glyph->glyph.y()==4.5f&&glyph.light()==LightCoordsUtil.FULL_BRIGHT&&glyph.color()==0xF95391E1))throw new AssertionError("Actual selected blue glowing source row is not native full-bright text");var manual=entity.getLines().getFirst().getSections().getFirst();if(entity.getLines().get(2).getSections().size()!=2||entity.getMaxCharCount()!=17||manual.flapCount()!=17||!manual.getText().getString().equals(MANUAL)||!manual.getRenderedText().equals("CREATE NATIVE 26."))throw new AssertionError("Real native source component/section/capacity text is missing: raw="+manual.getText()+", rendered="+manual.getRenderedText()+", flaps="+manual.flapCount());for(var block:AllBlocks.DISPLAY_BOARD.getStateDefinition().getPossibleStates())if(client.getModelManager().getBlockStateModelSet().get(block)==client.getModelManager().getBlockStateModelSet().missingModel())throw new AssertionError("Missing actual native board blockstate "+block);
        var mesh=Renderer.get().mutableMesh();client.getModelManager().getBlockStateModelSet().get(entity.getBlockState()).emitQuads(mesh.emitter(),client.level,P,entity.getBlockState(),RandomSource.create(42),side->false);if(mesh.size()!=20)throw new AssertionError("Actual source board requires20static shell quads");mesh.forEach(quad->{if(quad.chunkLayer()!=ChunkSectionLayer.CUTOUT)throw new AssertionError("Real native board source cutout layer missing");});state.cog.mesh.forEach(quad->{if(quad.chunkLayer()!=ChunkSectionLayer.CUTOUT)throw new AssertionError("Real moving shaftless cog source cutout layer missing");});
        for(int y=0;y<2;y++)for(int x=0;x<4;x++){var child=(FlapDisplayBlockEntity)LoadedLevelAccess.blockEntity(client.level,P.east(x).below(y));if(child.getController()!=entity)throw new AssertionError("Actual client rectangle controller differs between real board parts");}
    });}
    private static void use(ClientGameTestContext context,int line){var pos=P.east().below(line/2);look(context,new Vec3(pos.getX()+.5,pos.getY()+.75-(line%2)*.5,pos.getZ()+13/16d));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(pos),150);context.waitTicks(6);context.getInput().pressKey(options->options.keyUse);}
    private static void slot(TestSingleplayerContext world,int slot,ItemStack stack){world.getServer().runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();player.getInventory().setItem(slot,stack.copy());player.connection.send(player.getInventory().createInventoryUpdatePacket(slot));});}
    private static FlapDisplayBlockEntity part(ServerLevel level,BlockPos pos){return LoadedLevelAccess.blockEntity(level,pos)instanceof FlapDisplayBlockEntity board?board:null;}
    private static FlapDisplayBlockEntity board(ServerLevel level){return part(level,P);}
    private static String text(ServerLevel level,int line){var board=board(level);if(board==null)return"";var component=board.getLines().get(line).getSections().getFirst().getText();return component==null?"":component.getString();}
    private static void block(TestSingleplayerContext world,BlockPos pos,String state){world.getServer().runCommand("setblock "+pos.getX()+" "+pos.getY()+" "+pos.getZ()+" "+state);}
    private static void screenshot(ClientGameTestContext context,String name){context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot(name);}
    private static void look(ClientGameTestContext context,Vec3 target){var angle=context.computeOnClient(client->{var delta=target.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(angle.x,angle.y);}
    private static void waitServer(ClientGameTestContext context,TestSingleplayerContext world,Predicate<ServerLevel> condition,int ticks,String message){var ready=new AtomicBoolean();for(int tick=0;tick<ticks&&!ready.get();tick++){world.getServer().runOnServer(ignored->ready.set(condition.test(world.getConnection().getServerLevel())));if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError(message);}
}
